from pathlib import Path
import json
rows={
'qingcheng-six-senses':('青城山六善｜在山脚住三晚，文化参访与休息各留一天','以青城山及都江堰文化环境为背景，酒店官网提供住宿、水疗与周边探索信息。适合希望在度假设施与短途文化游览之间切换的人。','先比较套房与别墅的动线、同住人数和私密程度。带长辈重点问步行距离、接驳和台阶；“靠近青城山”不代表从房间走几步就能进入景区。','从成都方向抵达后落实最后一段酒店接送；青城山与都江堰分开安排，景区活动与酒店课程分别预约。','酒店用餐与周边川菜可以交替，提前说明过敏、辣度和特殊饮食。不要默认康养住宿包含全部餐食。',['抵达后熟悉园区：先确认餐厅、活动表与水疗预约，再沿短线散步。','青城山文化半日：按天气选开放路线，下午回酒店休息；水疗另约，不和长时间登山叠加。','都江堰或园区体验二选一：喜欢文化可了解水利工程，想轻松则留在酒店；体验项目按当天排期。'],'sixsenses'),
'amanfayun':('杭州法云安缦｜把西湖行程留白，走进茶田与寺院之间','官网描述其位于茶田与林地环绕的谷地，石径连接院落与不同布局的房舍。旅行重点是村落式空间、周边寺院文化和茶的日常，而不是城市地标打卡。','每间房布局不同，先问院落或林景、台阶、采光和浴室动线。带长辈不只看房型面积，应索要到餐厅的步行说明。','西湖与法云区域分日安排；节假日寺院周边交通可能拥堵，确认司机下客点和行李接驳。','可沿法云径了解餐饮选择；素食需求提前确认，不把寺院周边餐食都当作纯素。茶饮按耐受程度选择。',['抵达后沿法云径认识院落：不赶西湖日落，留时间看建筑与竹木。','寺院文化半日：尊重参访礼仪，下午了解茶或预约水疗，避免把多个寺院排成竞速路线。','西湖或再留半日山谷：选一种节奏，返程前不要跨城补景点。'],'amanfayun'),
'amanyangyun':('上海养云安缦｜一个不必赶往市中心的文化周末','官网介绍古宅、香樟、湖泊与楠书房文化空间，并设餐饮、水疗与家庭活动。适合想在上海外围度过两三天、以园区文化体验为重点的旅客。','现代套房与多卧古宅别墅的居住方式差异大。朋友同行先分清卧室、公共空间、私池与儿童安全安排；不是人数多就一定适合拼住。','按实际出发机场或城区确认接送。把市中心购物与园区停留分日，避免每天往返消耗休息时间。','官网列有多个餐饮选择及花园相关体验；餐厅、下午茶与活动分别核对预约和价格。不要默认住宿包含所有体验。',['先看香樟与古宅：抵达后园区散步，了解修复建筑的背景。','楠书房与园区慢生活：文化活动按排期预约，午后安排水疗或安静阅读。','湖畔早餐与短途骑行：使用开放路线，亲子活动先核实年龄和看护规则。'],'amanyangyun'),
'zulal':('Zulal｜先选成人静修，还是一家人的康养假期','官网明确区分 Serenity 成人静修与 Discovery 家庭体验。比起先选房型，先决定同行者是否需要安静独处、儿童活动和共同用餐，才不容易订错区域。','核对成人区域年龄政策与家庭区入住规则。询问同行儿童活动、看护责任和成人项目能否错时安排，不能默认儿童可进入全部水疗区域。','酒店位于卡塔尔北端海滨，机场抵达后安排车辆；转场日不预约紧接航班的收费项目。炎热天气户外放在较凉时段。','了解套餐餐食范围、过敏与咖啡因安排。传统阿拉伯与伊斯兰医学是酒店文化定位，具体健康干预仍需评估适用性。',['抵达与目标沟通：告诉团队最想改善的生活习惯，先看实际活动表。','围绕一个目标安排：成人可选放松与轻活动，家庭给共同活动留一段完整时间。','把计划带回家：请团队写下可执行的日常建议，另确认未含费用后离店。'],'zulal'),
'euphoria':('Euphoria｜米斯特拉斯的文化风景，与一段安静住宿','官网将其定位为伯罗奔尼撒地区的康养度假酒店，结合水疗、活动与米斯特拉斯周边文化环境。适合愿意为陆路转场留时间、把文化参访和静修分日的旅客。','先确认房间位置、坡道和到水疗的距离。普通住宿、水疗使用与具体医学项目可能不同，要求分项说明而不是只看套餐名称。','询问适合航班的机场与道路接送方案，明确等候和晚到政策。米斯特拉斯参访存在台阶，不安排在高温正午。','在酒店用餐前说明过敏和饮食限制，了解是否强制遵循特定餐食；希望自由选择者先比较普通住宿和项目套餐。',['抵达后先看水疗动线：确认开放设施与预约方式，不在疲劳转场后连续做项目。','米斯特拉斯文化半日：按体能选择参访范围，午后休息；大热天缩短户外。','选择一项真正想体验的活动：水疗、轻运动或工作坊按确认排期参加，其余时间留白。'],'euphoria')}
out={}
for key,(title,summary,base,transport,food,days,source) in rows.items():
 d=json.loads(Path('output/travel-research/'+source+'-expanded.json').read_text(encoding='utf-8'))
 out['hotel-'+key]={'summary':title+'。'+summary,'base':base,'transport':transport,'food':food,'packing':'泳衣、舒适步行鞋与日常药物；如参加评估，携带近期报告、用药及过敏信息。着装与设施规则提前询问。','budget':'将房费、税费、餐食、水疗次数、咨询评估、接送及取消条件分项核对。官网限时活动不等于平台可售权益。','days':[{'title':f'住宿第{i+1}天','morning':x,'afternoon':'只追加一个已确认的项目，其余时间留给用餐与恢复。','evening':'住宿附近用餐，按自己的节奏休息。','practical':'这是编辑安排，不是酒店确认套餐；活动时间与费用须另行核实。','rain':'改用已开放的室内空间；设施预约与身体适用条件由酒店确认。'} for i,x in enumerate(days)],'photos':[{'src':'/static/assets/hotels/'+key+'.jpg','caption':'酒店公开资料中的度假环境','credit':'酒店官方资料','source':d['url']}],'sources':[{'name':'酒店官方网站','url':d['url']}],'checked':'2026-10-04'}
p=Path('frontend/travel-domestic-guides.js');p.write_text(p.read_text(encoding='utf-8')+'Object.assign(detailedTravelGuides,'+json.dumps(out,ensure_ascii=False,indent=2)+');\n',encoding='utf-8')
p=Path('frontend/hotels.js');s=p.read_text(encoding='utf-8');start=s.index('<section class="lifestyle-note"><h2>無龄岛会员礼遇');end=s.index('<section><h2>無龄岛专属咨询',start);s=s[:start]+'<section class="lifestyle-note"><h2>同一预算，怎么选更值</h2><p>先保证房间安静、交通方便和餐食合适，再比较项目数量。要求对方把实际可用的设施、单次项目时长与额外收费写清；同行者目标不同，可以分别选择项目。</p></section>'+s[end:];p.write_text(s,encoding='utf-8')
